from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Cell_trace_format(EmssimCommand):
    def __init__(self, method="cell_trace_format", timeout=60, rpc_connection_name='localRPC'):
        super(Cell_trace_format, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Cell_trace_format, self).on_new_data(**data)
        if "msg" in data:
            if (data["msg"] == "warning occured"):
                if (data["warning"] == "No active Cell Trace process"):
                    self._ret['cell_trace_active'] = False
            elif (data["msg"] == "cell trace formats"):
                self._ret['cell_trace_active'] = True
                self._ret['current_cell_trace_format'] = data["current_trace_format"]
                self._ret['current_cell_trace_log_file'] = data["current_trace_log_file"]
        elif ("status" in data):
            self._ret["status"] = data["status"]
